item.content:encoded:
.footer-wrapper, .footer {
	display:none;
}
.entry-categories, .category {
	display:none!important;
}
.entry-social {
	display:none;
}

.navbar {
	box-shadow:none;
	border-bottom:1px solid #eee
}
h1.title-in-content {
	margin-bottom:25px!important;
}
hr {
	display:none;
}
button, .top-install {
	display:inline-block;
	padding:10px 15px;
	border-radius:20px;
	font-weight:600;
	background:#3c4858;
	color:#fff;
}
button:hover, .top-install:hover {
	background:#3c4858!important;
	opacity:0.75;
}

.navbar-brand img {
	max-height:40px;
}
.navbar-nav>li a {
	    padding: 2px!important;
}

.main-raised {
	box-shadow:0 0 40px rgba(0,0,0,0.05)
}

.image-in-page {display:none;}

.single-post-wrap a {
	color: #2f6b9a;
	font-weight:600;
	transition:.3s;
}
.single-post-wrap a:hover {
	color: #23527c;
}

.blocks-gallery-item {
	margin-bottom:6px!important;
}
.wp-block-gallery {
	margin-bottom:15px;
}
figcaption {
	width:100%;
	text-align:center;
}

.wp-block-code {
	  background: #272822;
		color:#fff;
    border: 0;
    box-shadow: 2px 2px 10px rgba(0,0,0,0.05);
    border-radius: 20px;
    padding: 25px;
}

.hljs{display:block;overflow-x:auto;padding:.5em;background:#272822;color:#ddd}.hljs-tag,.hljs-keyword,.hljs-selector-tag,.hljs-literal,.hljs-strong,.hljs-name{color:#f92672}.hljs-code{color:#66d9ef}.hljs-class .hljs-title{color:white}.hljs-attribute,.hljs-symbol,.hljs-regexp,.hljs-link{color:#bf79db}.hljs-string,.hljs-bullet,.hljs-subst,.hljs-title,.hljs-section,.hljs-emphasis,.hljs-type,.hljs-built_in,.hljs-builtin-name,.hljs-selector-attr,.hljs-selector-pseudo,.hljs-addition,.hljs-variable,.hljs-template-tag,.hljs-template-variable{color:#a6e22e}.hljs-comment,.hljs-quote,.hljs-deletion,.hljs-meta{color:#75715e}.hljs-keyword,.hljs-selector-tag,.hljs-literal,.hljs-doctag,.hljs-title,.hljs-section,.hljs-type,.hljs-selector-id{font-weight:bold}

.navbar {
	position:absolute!important;
}

.wp-block-image img {
    margin: 40px auto 40px;
    display: block;
	max-width:90%;
}
.wp-block-image figcaption {
	margin-top:-25px!important;
	margin-bottom:35px!important;
}
.wp-block-image {
	margin-bottom:40px;
}

body {
	font-weight:400;
}

.post-views {
	margin-bottom:10px;
}

.emailoctopus-form * {
	margin:0;
	margin-bottom:0!important;
}
.emailoctopus-form h2 {
	font-size:34px!important;
	padding-top:0;
}
.emailoctopus-form p {
	margin-bottom:10px!important;
	font-size:16px!important;
}
.emailoctopus-form input {
	border-radius:20px!important;
}
.emailoctopus-label {
	margin-left:10px;
	margin-bottom:4px!important;
}
.emailoctopus-form-wrapper {
	margin-top: 60px;
    border-radius: 0;
    background-color: #fff;
    border: 1px solid #eee;
}

.single-post-wrap, .comments-area {
	max-width:650px;
	margin:auto;
}

blockquote {
	  background: #fafafa;
    border-radius: 8px;
    border-left-width: 10px;
    font-style: normal!important;
	padding:20px 30px;
}
blockquote p {
	font-style:normal!important;
}

/* social icons adjustment */
.btn.btn-just-icon {
    box-shadow: none!important;
}

.section-blog-info {
	padding-bottom:0;
}

/* Related Posts */
.related-posts .card {
	box-shadow:0px 0px 30px 1px rgba(0,0,0,0.05);
	cursor:pointer;
	transition:.3s;
}
.related-posts .card:hover {
	box-shadow:0  0 30px 10px rgba(0,0,0,0.05);
}
.related-posts .card .card-image {
	margin:0!important;
	box-shadow:none;
	border-radius:5px 5px 0 0;
}
.related-posts .card .card-image img {
	border-radius:0!important;
}

.card-image {
	box-shadow:none!important;
}

.simplesocialbuttons {
	margin-left:15px!important;
}

h2, h3, h4, h5, h6 {
	line-height: 1.3!important;
	margin-top:40px!important;
	font-weight:600;
}

body, .main, nav.navbar {
	background: #f9f9f9!important;
}

.entry-content a {
	font-weight: 600;
	border-bottom:1px solid #ffd969;
}

code {
    padding: 2px 4px;
    font-size: 90%;
    background-color: #f9f2f4;
    border-radius: 4px;
}

.wp-block-code {
	  background: #272822;
		color:#fff;
    border: 0;
    box-shadow: 2px 2px 10px rgba(0,0,0,0.05);
    border-radius: 20px;
    padding: 20px 25px;
	  font-size:13px;
}

pre code {
    padding: 0;
    font-size: inherit;
    color: inherit;
    white-space: pre-wrap;
    background-color: transparent;
    border-radius: 0;
}

.hljs{display:block;overflow-x:auto;padding:.5em;background:#272822;color:#ddd}.hljs-tag,.hljs-keyword,.hljs-selector-tag,.hljs-literal,.hljs-strong,.hljs-name{color:#f92672}.hljs-code{color:#66d9ef}.hljs-class .hljs-title{color:white}.hljs-attribute,.hljs-symbol,.hljs-regexp,.hljs-link{color:#bf79db}.hljs-string,.hljs-bullet,.hljs-subst,.hljs-title,.hljs-section,.hljs-emphasis,.hljs-type,.hljs-built_in,.hljs-builtin-name,.hljs-selector-attr,.hljs-selector-pseudo,.hljs-addition,.hljs-variable,.hljs-template-tag,.hljs-template-variable{color:#a6e22e}.hljs-comment,.hljs-quote,.hljs-deletion,.hljs-meta{color:#75715e}.hljs-keyword,.hljs-selector-tag,.hljs-literal,.hljs-doctag,.hljs-title,.hljs-section,.hljs-type,.hljs-selector-id{font-weight:bold}

.wp-block-image {
	margin:40px auto;
}

.wp-block-image img {
    margin: auto;
    display: block;
    max-width: 95%;
		box-shadow:2px 2px 15px 5px rgba(0,0,0,0.1);
	border-radius:5px;
}

.post-views {
    margin-bottom: 10px;
		font-size:12px;
}

figcaption {
	margin-top:10px!important;
}
figcaption em {
	font-style:normal!important;
}
